// Build/distribution guard. A real `npm install -g disputatio@0.2.0` crashed because the
// bin was a `.ts` file — Node refuses to type-strip TypeScript under node_modules. The fix
// ships a bundled `.js` bin. Then a SECOND bug: a shebang in src + a `--banner:js` shebang
// produced TWO `#!` lines, and the line-2 one is a syntax error. This test guards both:
// the published bin must be runnable JS with exactly one shebang, on line 1.
//
// Depends on esbuild (a devDependency), so it SKIPS on a zero-dep clone (`node --test`
// without `npm install`) and runs once dependencies are installed.

import { test } from "node:test";
import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { readFile, access } from "node:fs/promises";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const execFileAsync = promisify(execFile);
const root = join(dirname(fileURLToPath(import.meta.url)), "..");

const esbuildPresent = await access(join(root, "node_modules/.bin/esbuild")).then(() => true, () => false);

test(
  "published bundle: JS bin with a single line-1 shebang that runs",
  { skip: esbuildPresent ? false : "esbuild not installed (zero-dep clone)" },
  async () => {
    await execFileAsync("npm", ["run", "build"], { cwd: root });
    const dist = join(root, "dist", "index.js");
    const lines = (await readFile(dist, "utf8")).split("\n");
    assert.equal(lines[0], "#!/usr/bin/env node", "line 1 must be the shebang");
    assert.ok(!lines.slice(1).some((l) => l.startsWith("#!")), "no second shebang (the double-shebang regression)");
    // The bin must actually load + run (the bundle, end to end). --help exits 0 to stderr.
    const r = await execFileAsync("node", [dist, "--help"]).catch((e: { stdout?: string; stderr?: string }) => e);
    assert.match((r.stderr ?? "") + (r.stdout ?? ""), /usage: disputatio/);
  },
);
// Install / --init tests. resolveBinary's "pin only when needed" branching is tested as
// a pure function (injected canary); runInit is tested through dependency injection —
// a stub buildParticipant whose canary verdict is driven by the bin, so no real CLI is
// spawned. The codex stale-shim scenario (PATH binary fails, a brew path works) is the
// motivating case and the thing we assert end-to-end.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { resolveBinary, runInit } from "../src/install.ts";
import type { ParticipantSpec } from "../src/config.ts";
import type { Participant } from "../src/adapters.ts";

// --- resolveBinary (pure) -------------------------------------------------------------

test("resolveBinary: PATH binary works → ok, no pin, alternatives untouched", async () => {
  let calls = 0;
  const res = await resolveBinary("codex", ["/opt/homebrew/bin/codex"], async (bin) => { calls++; return bin === "codex"; });
  assert.deepEqual(res, { ok: true, tried: ["codex"] });
  assert.equal(calls, 1); // short-circuits — never canaries the alternative
});

test("resolveBinary: PATH binary fails, an alternative works → pin that alternative", async () => {
  const res = await resolveBinary("codex", ["/n/a/codex", "/opt/homebrew/bin/codex"], async (bin) => bin === "/opt/homebrew/bin/codex");
  assert.equal(res.ok, true);
  assert.equal(res.bin, "/opt/homebrew/bin/codex");
});

test("resolveBinary: nothing works → ok:false, no bin", async () => {
  const res = await resolveBinary("codex", ["/opt/homebrew/bin/codex"], async () => false);
  assert.equal(res.ok, false);
  assert.equal(res.bin, undefined);
});

// --- runInit (DI) ---------------------------------------------------------------------

// A stub lineup factory: the canary verdict is whether the spec's effective binary is in
// `working`. runInit's default canary is runIsolated → p.run, which for a stub never
// spawns a real CLI.
function stubBuild(working: Set<string>) {
  return (spec: ParticipantSpec): Participant => ({
    id: spec.adapter,
    display: spec.adapter,
    vendor: spec.adapter,
    run: async () => (working.has(spec.bin ?? spec.adapter) ? { ok: true, text: "pong" } : { ok: false, error: "stale shim" }),
  });
}

const JUDGE: ParticipantSpec = { adapter: "claude", model: "opus", effort: "high", maxBudgetUsd: 2 };
const tmpCfg = () => join(tmpdir(), `disputatio-init-${process.pid}-${Math.floor(performance.now())}.yaml`);

test("runInit: codex stale shim → brew bin pinned; claude on PATH → no bin; judge seeded", async () => {
  const cfgPath = tmpCfg();
  try {
    const res = await runInit(
      [{ adapter: "claude" }, { adapter: "codex" }],
      JUDGE,
      cfgPath,
      { force: true, deps: {
        buildParticipant: stubBuild(new Set(["claude", "/opt/homebrew/bin/codex"])),
        findAlternatives: async (bin) => (bin === "codex" ? ["/opt/homebrew/bin/codex"] : []),
      } },
    );
    assert.equal(res.exitCode, 0);
    const written = await readFile(cfgPath, "utf8");
    assert.match(written, /adapter: codex/);
    assert.match(written, /bin: \/opt\/homebrew\/bin\/codex/); // pinned because PATH codex failed
    // claude block must NOT carry a bin (PATH binary worked)
    const claudeBlock = written.slice(written.indexOf("adapter: claude"), written.indexOf("adapter: codex"));
    assert.ok(!/bin:/.test(claudeBlock), `claude should have no bin, got: ${claudeBlock}`);
    // judge seeded
    assert.match(written, /judge:/);
    assert.match(written, /model: opus/);
  } finally {
    await rm(cfgPath, { force: true });
  }
});

test("runInit: PATH binaries all work → no bin pinned (only-when-needed)", async () => {
  const cfgPath = tmpCfg();
  try {
    const res = await runInit(
      [{ adapter: "claude" }, { adapter: "codex" }],
      undefined,
      cfgPath,
      { force: true, deps: {
        buildParticipant: stubBuild(new Set(["claude", "codex"])),
        findAlternatives: async () => ["/opt/homebrew/bin/codex"], // present, but never needed
      } },
    );
    assert.equal(res.exitCode, 0);
    const written = await readFile(cfgPath, "utf8");
    assert.ok(!/bin:/.test(written), `no bin should be pinned, got:\n${written}`);
    assert.ok(!/judge:/.test(written), "no judge when none passed");
  } finally {
    await rm(cfgPath, { force: true });
  }
});

test("runInit: a participant with no working binary → exit 1, config not written", async () => {
  const cfgPath = tmpCfg();
  const res = await runInit(
    [{ adapter: "claude" }, { adapter: "codex" }],
    undefined,
    cfgPath,
    { force: true, deps: {
      buildParticipant: stubBuild(new Set(["claude"])), // codex broken everywhere
      findAlternatives: async () => [],
    } },
  );
  assert.equal(res.exitCode, 1);
  await assert.rejects(() => readFile(cfgPath, "utf8")); // nothing written
});
// Config resolution tests — the 3-step precedence behind a no-`--config` run, and the
// XDG-aware user config path. This is the P2 regression guard: a bare run on a foreign
// machine must NOT auto-load the host-specific examples/debate.yaml; it must fall through
// to the built-in lineup (text:null).

import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, mkdir, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { userConfigPath, resolveConfigText } from "../src/install.ts";
import { parseDebateConfig } from "../src/config.ts";

test("userConfigPath honors XDG_CONFIG_HOME, else ~/.config", () => {
  assert.equal(
    userConfigPath({ XDG_CONFIG_HOME: "/x/cfg" }),
    join("/x/cfg", "disputatio", "config.yaml"),
  );
  const home = userConfigPath({ HOME: "<user-home>" } as NodeJS.ProcessEnv);
  assert.match(home, /[/\\]\.config[/\\]disputatio[/\\]config\.yaml$/);
});

test("no --config + no user config → built-in lineup (text:null) — the P2 guard", async () => {
  const xdg = await mkdtemp(join(tmpdir(), "disputatio-xdg-"));
  try {
    const { text, source } = await resolveConfigText(undefined, { XDG_CONFIG_HOME: xdg });
    assert.equal(text, null); // → index.ts uses DEFAULT_SPECS, no /opt/homebrew assumption
    assert.match(source, /built-in/);
  } finally {
    await rm(xdg, { recursive: true, force: true });
  }
});

test("no --config but user config present → loads it", async () => {
  const xdg = await mkdtemp(join(tmpdir(), "disputatio-xdg-"));
  try {
    await mkdir(join(xdg, "disputatio"), { recursive: true });
    await writeFile(join(xdg, "disputatio", "config.yaml"), "participants:\n  - adapter: claude\n  - adapter: codex\n");
    const { text, source } = await resolveConfigText(undefined, { XDG_CONFIG_HOME: xdg });
    assert.ok(text && text.includes("adapter: claude"));
    assert.equal(source, join(xdg, "disputatio", "config.yaml"));
    assert.equal(parseDebateConfig(text!).participants?.length, 2);
  } finally {
    await rm(xdg, { recursive: true, force: true });
  }
});

test("explicit --config that does not exist → hard-fails (does not silently fall back)", async () => {
  await assert.rejects(() => resolveConfigText(join(tmpdir(), "does-not-exist-xyz.yaml"), {}));
});

test("a malformed user config still surfaces (parse throws downstream, not swallowed)", async () => {
  const xdg = await mkdtemp(join(tmpdir(), "disputatio-xdg-"));
  try {
    await mkdir(join(xdg, "disputatio"), { recursive: true });
    await writeFile(join(xdg, "disputatio", "config.yaml"), "participants:\n  - adapter: bogus\n  - adapter: codex\n");
    const { text } = await resolveConfigText(undefined, { XDG_CONFIG_HOME: xdg });
    assert.ok(text !== null); // resolution returns the text...
    assert.throws(() => parseDebateConfig(text!)); // ...and the bad adapter fails at parse, not here
  } finally {
    await rm(xdg, { recursive: true, force: true });
  }
});
// doctor (M0 preflight) tests — exercise the orchestration seam with STUB
// Participants (canned `run`), not real CLIs. The CLI transport / success
// classification is already covered by adapters.test.ts; here we only test that
// the canary fan-out, classification, allHealthy gate, and report formatting
// behave. Stubs also keep the shared FAKE_STDOUT_FILE env from colliding when
// claude+codex canary in parallel.

import { test } from "node:test";
import assert from "node:assert/strict";
import { runDoctor, allHealthy, formatDiagnoses } from "../src/doctor.ts";
import type { Participant, AgentResult } from "../src/adapters.ts";

function stub(id: string, vendor: string, result: AgentResult): Participant {
  return { id, display: `${id} (stub)`, vendor, run: async () => result };
}

test("doctor: all participants answer the canary → all ok, allHealthy true", async () => {
  const ds = await runDoctor([
    stub("claude", "anthropic", { ok: true, text: "pong" }),
    stub("codex", "openai", { ok: true, text: "pong" }),
  ]);
  assert.equal(ds.length, 2);
  assert.ok(ds.every((d) => d.ok));
  assert.equal(allHealthy(ds), true);
});

test("doctor: one participant fails → that diagnosis ok:false and allHealthy false", async () => {
  const ds = await runDoctor([
    stub("claude", "anthropic", { ok: true, text: "pong" }),
    stub("codex", "openai", { ok: false, error: "binary not runnable (exit 127) — check PATH / asdf shims" }),
  ]);
  assert.equal(allHealthy(ds), false);
  const codex = ds.find((d) => d.id === "codex");
  assert.equal(codex?.ok, false);
  // raw error excerpt must survive into the diagnosis so the codex stale-shim
  // footgun (0.1.x shadowing 0.139.0) is diagnosable from doctor output alone.
  assert.match(codex?.detail ?? "", /asdf shims/);
});

test("doctor: a participant that throws is reported as unhealthy, not crash the run", async () => {
  const ds = await runDoctor([
    stub("claude", "anthropic", { ok: true, text: "pong" }),
    { id: "boom", display: "boom", vendor: "x", run: async () => { throw new Error("kaboom"); } },
  ]);
  assert.equal(allHealthy(ds), false);
  assert.match(ds.find((d) => d.id === "boom")?.detail ?? "", /kaboom/);
});

test("doctor: report shows a per-participant marker, vendor, and the failing detail", async () => {
  const ds = await runDoctor([
    stub("claude", "anthropic", { ok: true, text: "pong" }),
    stub("codex", "openai", { ok: false, error: "not authenticated" }),
  ]);
  const report = formatDiagnoses(ds);
  assert.match(report, /claude/);
  assert.match(report, /anthropic/);
  assert.match(report, /not authenticated/);
  assert.match(report, /1\/2/); // healthy count summary
});
// Adapter classifier tests — run against fake CLIs (test/fakes/*) that replay
// envelopes captured from REAL runs (research/canary-results.md + the
// 2026-06-11 budget-exceeded canary). The fakes shadow the real binaries via PATH.

import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { tmpdir } from "node:os";
import { claudeAdapter, agyAdapter, codexAdapter, piAdapter, copilotCliAdapter } from "../src/adapters.ts";

const here = dirname(fileURLToPath(import.meta.url));
const fixtures = join(here, "fixtures");
process.env.PATH = `${join(here, "fakes")}:${process.env.PATH}`;

const cwd = tmpdir();

beforeEach(() => {
  for (const k of Object.keys(process.env)) if (k.startsWith("FAKE_")) delete process.env[k];
});

// --- claude: JSON envelope ------------------------------------------------------------

test("claude: success envelope → ok with text and cost", async () => {
  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-success.json");
  const r = await claudeAdapter().run("ping", cwd);
  assert.equal(r.ok, true);
  assert.equal(r.ok && r.text, "pong");
  assert.equal(r.ok && r.costUsd, 0.10388775);
});

test("claude: --max-budget-usd defaults to $5, overridable via maxBudgetUsd", async () => {
  const argvFile = join(tmpdir(), `disputatio-claude-argv-${process.pid}.txt`);
  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-success.json");
  process.env.FAKE_ARGV_FILE = argvFile;

  await claudeAdapter().run("ping", cwd);
  let argv = readFileSync(argvFile, "utf8").split("\n");
  assert.equal(argv[argv.indexOf("--max-budget-usd") + 1], "5");

  await claudeAdapter("sonnet", { maxBudgetUsd: 10 }).run("ping", cwd);
  argv = readFileSync(argvFile, "utf8").split("\n");
  assert.equal(argv[argv.indexOf("--max-budget-usd") + 1], "10");
});

test("claude: effort is passed as --effort when set, omitted when absent", async () => {
  const argvFile = join(tmpdir(), `disputatio-claude-argv-${process.pid}.txt`);
  process.env.FAKE_STDOUT_FILE = join(fixtures, "claude-success.json");
  process.env.FAKE_ARGV_FILE = argvFile;

  await claudeAdapter("sonnet", { effort: "high" }).run("ping", cwd);
  let argv = readFileSync(argvFile, "utf8").split("\n");
  assert.ok(argv.includes("--effort"), "expected --effort in argv");
  assert.equal(argv[argv.indexOf("--effort") + 1], "high");

  await claudeAdapter("sonnet").run("ping", cwd);
  argv = readFileSync(argvFile, "utf8").split("\n");
  assert.ok(!argv.includes("--effort"), "expected no --effort when effort is unset");
});

test("codex: effort is passed as model_reasoning_effort override when set, omitted when absent", async () => {
  const argvFile = join(tmpdir(), `disputatio-codex-argv-${process.pid}.txt`);
  process.env.FAKE_STDOUT_FILE = join(fixtures, "codex-success.jsonl");
  process.env.FAKE_ARGV_FILE = argvFile;

  await codexAdapter(undefined, { bin: join(here, "fakes", "codex"), effort: "high" }).run("ping", cwd);
  let argv = readFileSync(argvFile, "utf8").split("\n");
  assert.ok(argv.includes(`model_reasoning_effort="high"`), `expected the config override in argv, got ${JSON.stringify(argv)}`);

  await codexAdapter(undefined, { bin: join(here, "fakes", "codex") }).run("ping", cwd);
  argv = readFileSync(argvFile, "utf8").split("\n");
  assert.ok(!argv.some((a) => a.startsWith("model_reasoning_effort")), "expected no effort override when unset");
