});

test("a malformed user config still surfaces (parse throws downstream, not swallowed)", async () => {
  const xdg = await mkdtemp(join(tmpdir(), "disputatio-xdg-"));
  try {
    await mkdir(join(xdg, "disputatio"), { recursive: true });
