function overlayConfig(parent: DebateConfig, child: DebateConfig): DebateConfig {
  const merged = { ...parent, ...child };
  if (parent.participants && child.participants) {
    merged.participants = [...parent.participants];
    for (const spec of child.participants) {
      const index = merged.participants.findIndex((inherited) => inherited.adapter === spec.adapter);
