    await writeFile(bundlePath, JSON.stringify({
      version: 1,
      profiles: { base: { config: "base.yaml" }, child: { extends: "base", config: "child.yaml" } },
    }));
    await writeFile(join(dir, "base.yaml"), parentText);
    await writeFile(join(dir, "child.yaml"), childText);
    const bundleText = await readFile(bundlePath, "utf8");

    const first = await loadProfileBundle(bundlePath, "child");
    const second = await loadProfileBundle(bundlePath, "child");
    first.participants![0].model = "changed";
    first.participants!.push({ adapter: "pi" });
    first.judge!.model = "changed";
    assert.deepEqual(second.participants, [
      { adapter: "claude", model: "haiku" },
      { adapter: "pi" },
    ]);
    assert.deepEqual(second.judge, { adapter: "claude", model: "opus" });
    assert.deepEqual(await loadProfileBundle(bundlePath, "child"), second);
    assert.equal((await loadProfileBundle(bundlePath, "base")).participants?.[0].model, "sonnet");
    assert.equal(await readFile(bundlePath, "utf8"), bundleText);
    assert.equal(await readFile(join(dir, "base.yaml"), "utf8"), parentText);
    assert.equal(await readFile(join(dir, "child.yaml"), "utf8"), childText);
  });
});

