import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { loadProfileBundle } from "../src/profile-bundle.ts";

const CONFIG = [
  "rounds: 2",
  "participants:",
  "  - adapter: claude",
  "    model: sonnet",
  "  - adapter: codex",
  "judge:",
  "  adapter: claude",
  "  model: opus",
  "",
].join("\n");

async function inTempDir(run: (dir: string) => Promise<void>): Promise<void> {
  const dir = await mkdtemp(join(tmpdir(), "disputatio-profile-bundle-"));
  try {
    await run(dir);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

async function expectBundleError(
  action: () => Promise<unknown>,
  code: "INVALID_BUNDLE" | "UNKNOWN_PROFILE" | "PROFILE_REQUIRED" | "PROFILE_CYCLE",
): Promise<void> {
  await assert.rejects(action, (error: unknown) => {
    assert.ok(error instanceof Error);
    assert.equal((error as { code?: unknown }).code, code);
    return true;
  });
}

test("uses defaultProfile only when selection is omitted", async () => {
  await inTempDir(async (dir) => {
    const bundlePath = join(dir, "bundle.json");
    await writeFile(bundlePath, JSON.stringify({
      version: 1,
      defaultProfile: "fast",
      profiles: { fast: { config: "fast.yaml" }, slow: { config: "slow.yaml" } },
    }));
    await writeFile(join(dir, "fast.yaml"), CONFIG);
    await writeFile(join(dir, "slow.yaml"), CONFIG.replace("rounds: 2", "rounds: 7"));

    assert.equal((await loadProfileBundle(bundlePath)).rounds, 2);
    assert.equal((await loadProfileBundle(bundlePath, undefined)).rounds, 2);
    assert.equal((await loadProfileBundle(bundlePath, "slow")).rounds, 7);
    await expectBundleError(() => loadProfileBundle(bundlePath, ""), "UNKNOWN_PROFILE");
  });
});

test("requires a profile when no default exists, even for one or zero profiles", async () => {
  await inTempDir(async (dir) => {
    const bundlePath = join(dir, "bundle.json");
    for (const profiles of [{ only: { config: "only.yaml" } }, {}]) {
      await writeFile(bundlePath, JSON.stringify({ version: 1, profiles }));
      await expectBundleError(() => loadProfileBundle(bundlePath), "PROFILE_REQUIRED");
    }
  });
});

test("loads the selected config relative to its bundle and preserves source bytes", async () => {
  await inTempDir(async (dir) => {
    const bundlePath = join(dir, "profiles", "bundle.json");
    const configPath = join(dir, "profiles", "configs", "fast.yaml");
    const bundleText = '{\n  "version": 1,\n  "profiles": {\n    "fast": { "config": "configs/fast.yaml" }\n  }\n}\n';
    await mkdir(join(dir, "profiles", "configs"), { recursive: true });
    await writeFile(bundlePath, bundleText);
    await writeFile(configPath, CONFIG);

    const config = await loadProfileBundle(bundlePath, "fast");

    assert.equal(config.rounds, 2);
    assert.deepEqual(config.participants, [
      { adapter: "claude", model: "sonnet" },
      { adapter: "codex" },
    ]);
    assert.deepEqual(config.judge, { adapter: "claude", model: "opus" });
    assert.equal(await readFile(bundlePath, "utf8"), bundleText);
    assert.equal(await readFile(configPath, "utf8"), CONFIG);
  });
});

test("every load owns a fresh config tree, including participants and judge", async () => {
  await inTempDir(async (dir) => {
    const bundlePath = join(dir, "bundle.json");
    await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: { fast: { config: "fast.yaml" } } }));
    await writeFile(join(dir, "fast.yaml"), CONFIG);

    const first = await loadProfileBundle(bundlePath, "fast");
    const second = await loadProfileBundle(bundlePath, "fast");
    assert.notStrictEqual(first, second);
    assert.notStrictEqual(first.participants, second.participants);
    assert.notStrictEqual(first.participants?.[0], second.participants?.[0]);
    assert.notStrictEqual(first.judge, second.judge);

    first.participants![0].model = "changed";
    first.judge!.model = "changed";
    first.rounds = 99;
    first.participants!.push({ adapter: "pi" });
    assert.equal(second.participants?.[0].model, "sonnet");
    assert.equal(second.judge?.model, "opus");
    assert.deepEqual(await loadProfileBundle(bundlePath, "fast"), second);
    assert.equal(await readFile(join(dir, "fast.yaml"), "utf8"), CONFIG);
  });
});

test("invalid JSON, versions, and profiles containers have INVALID_BUNDLE", async () => {
  await inTempDir(async (dir) => {
    const bundlePath = join(dir, "bundle.json");
    for (const source of [
      "{ not JSON",
      "null",
      "[]",
      JSON.stringify({ profiles: {} }),
      JSON.stringify({ version: 2, profiles: {} }),
      JSON.stringify({ version: "1", profiles: {} }),
      JSON.stringify({ version: 1 }),
      JSON.stringify({ version: 1, profiles: null }),
      JSON.stringify({ version: 1, profiles: [] }),
      JSON.stringify({ version: 1, profiles: "fast" }),
    ]) {
      await writeFile(bundlePath, source);
      await expectBundleError(() => loadProfileBundle(bundlePath, "fast"), "INVALID_BUNDLE");
    }
  });
});

test("selected profiles must be objects with a non-blank config and/or extends", async () => {
  await inTempDir(async (dir) => {
    const bundlePath = join(dir, "bundle.json");
    for (const fast of [
      null,
      [],
      "fast.yaml",
      {},
      { config: 7 },
      { config: "" },
      { config: " \t " },
      { extends: 7 },
      { extends: "" },
      { extends: " \t " },
      { config: "fast.yaml", extends: 7 },
      { extends: "base", config: null },
    ]) {
      await writeFile(bundlePath, JSON.stringify({ version: 1, profiles: { fast } }));
      await expectBundleError(() => loadProfileBundle(bundlePath, "fast"), "INVALID_BUNDLE");
    }
  });
});

test("inherits a parent config when the selected profile only extends it", async () => {
  await inTempDir(async (dir) => {
    const bundlePath = join(dir, "bundle.json");
    await writeFile(bundlePath, JSON.stringify({
      version: 1,
      profiles: {
        base: { config: "base.yaml" },
        fast: { extends: "base" },
      },
    }));
    await writeFile(join(dir, "base.yaml"), CONFIG);

    assert.deepEqual(await loadProfileBundle(bundlePath, "fast"), await loadProfileBundle(bundlePath, "base"));
  });
});

test("each multi-level YAML lineup replaces the prior list in its supplied order", async () => {
  await inTempDir(async (dir) => {
    const bundlePath = join(dir, "bundle.json");
    await writeFile(bundlePath, JSON.stringify({
      version: 1,
      profiles: {
        base: { config: "base.yaml" },
        middle: { extends: "base", config: "middle.yaml" },
        child: { extends: "middle", config: "child.yaml" },
      },
    }));
    await writeFile(join(dir, "base.yaml"), [
      "rounds: 4",
      "repo: parent",
      "timeoutMinutes: 9",
      "participants:",
      "  - adapter: claude",
      "    model: sonnet",
      "    bin: parent-claude",
      "  - adapter: codex",
      "    model: base-model",
      "    effort: high",
      "judge:",
      "  adapter: claude",
      "  model: opus",
      "",
    ].join("\n"));
    await writeFile(join(dir, "middle.yaml"), [
      "rounds: 0",
      "participants:",
      "  - adapter: codex",
      "    model: middle-model",
      "  - adapter: pi",
      "    model: middle-pi",
      "  - adapter: agy",
      "    model: middle-agy",
      "",
    ].join("\n"));
    await writeFile(join(dir, "child.yaml"), [
      "repo: child",
      "participants:",
      "  - adapter: pi",
      "    bin: child-pi",
      "  - adapter: claude",
      "    model: child-claude",
      "judge:",
      "  adapter: codex",
      "",
    ].join("\n"));

    assert.deepEqual((await loadProfileBundle(bundlePath, "middle")).participants, [
      { adapter: "codex", model: "middle-model" },
      { adapter: "pi", model: "middle-pi" },
      { adapter: "agy", model: "middle-agy" },
    ]);
    await writeFile(bundlePath, JSON.stringify({ version: 1, defaultProfile: `p${depth - 1}`, profiles }));
    assert.equal((await loadProfileBundle(bundlePath)).rounds, 2);

    profiles.p0 = { extends: `p${depth - 1}` };
    await writeFile(bundlePath, JSON.stringify({ version: 1, defaultProfile: `p${depth - 1}`, profiles }));
    await expectBundleError(() => loadProfileBundle(bundlePath), "PROFILE_CYCLE");

    await writeFile(bundlePath, JSON.stringify({
      version: 1,
      profiles: { self: { extends: "self" }, first: { extends: "second" }, second: { extends: "first" } },
    }));
    await expectBundleError(() => loadProfileBundle(bundlePath, "self"), "PROFILE_CYCLE");
    await expectBundleError(() => loadProfileBundle(bundlePath, "first"), "PROFILE_CYCLE");
  });
});

test("applies parent overrides, child YAML, then child overrides", async () => {
  await inTempDir(async (dir) => {
    const bundlePath = join(dir, "bundle.json");
    await writeFile(bundlePath, JSON.stringify({
      version: 1,
      profiles: {
        base: { config: "base.yaml" },
        parent: {
          extends: "base",
          overrides: {
            rounds: 2,
            repo: "parent override",
            participants: [
              { adapter: "codex", model: "parent override" },
              { adapter: "pi", model: "parent pi" },
            ],
            judge: { adapter: "pi", model: "parent judge" },
          },
        },
        child: {
          extends: "parent",
          config: "child.yaml",
          overrides: {
            rounds: 4,
            participants: [
              { adapter: "pi", model: "child inline" },
              { adapter: "claude", model: "child inline claude" },
            ],
            judge: null,
          },
        },
      },
    }));
    await writeFile(join(dir, "base.yaml"), [
      "rounds: 1",
      "repo: base",
      "timeoutMinutes: 8",
      "participants:",
      "  - adapter: claude",
      "    model: base-claude",
      "  - adapter: codex",
      "    model: base-codex",
      "judge:",
      "  adapter: claude",
      "  model: base-judge",
