import { test } from "node:test";
import assert from "node:assert/strict";
import { chmod, mkdtemp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { execFile as execFileCallback } from "node:child_process";
import { promisify } from "node:util";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { parseDebateConfig, serializeDebateConfig } from "../src/config.ts";

const execFile = promisify(execFileCallback);
const cliPath = fileURLToPath(new URL("../src/profile-cli.ts", import.meta.url));

async function inTempDir(run: (dir: string) => Promise<void>): Promise<void> {
  const dir = await mkdtemp(join(tmpdir(), "disputatio-profile-cli-"));
  try {
    await run(dir);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

type CliResult = { code: number; stdout: string; stderr: string };

async function runCli(cwd: string, args: string[], sentinelDir?: string, marker?: string): Promise<CliResult> {
  try {
    const result = await execFile(process.execPath, [cliPath, ...args], {
      cwd,
      env: { PATH: sentinelDir ?? process.env.PATH, SENTINEL_MARKER: marker },
    });
    return { code: 0, stdout: result.stdout, stderr: result.stderr };
  } catch (error) {
    const failed = error as Error & { code?: number | string; stdout?: string; stderr?: string };
    return { code: typeof failed.code === "number" ? failed.code : 1, stdout: failed.stdout ?? "", stderr: failed.stderr ?? "" };
  }
}

test("renders the effective default or explicit profile as canonical YAML without launching agents", async () => {
  await inTempDir(async (dir) => {
    const profilesDir = join(dir, "profiles");
    const sentinelDir = join(dir, "sentinel-bin");
    const marker = join(dir, "sentinel-ran");
    await mkdir(profilesDir);
    await mkdir(sentinelDir);
    await writeFile(join(sentinelDir, "sentinel"), "#!/bin/sh\necho invoked > \"$SENTINEL_MARKER\"\n");
    await chmod(join(sentinelDir, "sentinel"), 0o755);
    const bundleText = JSON.stringify({
      version: 1,
      defaultProfile: "child",
      profiles: {
        base: { config: "base.yaml" },
        child: { extends: "base", config: "child.yaml", overrides: { repo: "inline", judge: null } },
      },
    }, null, 2);
    const baseText = [
      "rounds: 2",
      "timeoutMinutes: 8",
      "participants:",
      "  - adapter: claude",
      "    model: base-claude",
      "    bin: sentinel",
      "  - adapter: codex",
      "    model: base-codex",
      "    bin: sentinel",
      "judge:",
      "  adapter: claude",
      "  bin: sentinel",
      "",
    ].join("\n");
    const childText = [
      "rounds: 0",
      "participants:",
      "  - adapter: pi",
      "    model: child-pi",
      "    bin: sentinel",
      "  - adapter: claude",
      "    model: child-claude",
      "    bin: sentinel",
      "",
    ].join("\n");
    await writeFile(join(profilesDir, "bundle.json"), bundleText);
    await writeFile(join(profilesDir, "base.yaml"), baseText);
    await writeFile(join(profilesDir, "child.yaml"), childText);

    const child = {
      rounds: 0,
      repo: "inline",
      timeoutMinutes: 8,
      participants: [
        { adapter: "pi" as const, model: "child-pi", bin: "sentinel" },
        { adapter: "claude" as const, model: "child-claude", bin: "sentinel" },
      ],
    };
    const base = {
      rounds: 2,
      timeoutMinutes: 8,
      participants: [
        { adapter: "claude" as const, model: "base-claude", bin: "sentinel" },
        { adapter: "codex" as const, model: "base-codex", bin: "sentinel" },
      ],
      judge: { adapter: "claude" as const, bin: "sentinel" },
    };
    const defaultResult = await runCli(dir, ["--bundle", "profiles/bundle.json"], sentinelDir, marker);
    const explicitResult = await runCli(dir, ["--bundle=profiles/bundle.json", "--profile", "base"], sentinelDir, marker);
    assert.deepEqual(defaultResult, { code: 0, stdout: serializeDebateConfig(child), stderr: "" });
    assert.deepEqual(parseDebateConfig(defaultResult.stdout), child);
    assert.deepEqual(explicitResult, { code: 0, stdout: serializeDebateConfig(base), stderr: "" });
    await assert.rejects(() => readFile(marker), (error: unknown) => (error as NodeJS.ErrnoException).code === "ENOENT");
    assert.equal(await readFile(join(profilesDir, "bundle.json"), "utf8"), bundleText);
    assert.equal(await readFile(join(profilesDir, "base.yaml"), "utf8"), baseText);
    assert.equal(await readFile(join(profilesDir, "child.yaml"), "utf8"), childText);
  });
});

test("reports argument and loader failures on stderr without YAML output", async () => {
  await inTempDir(async (dir) => {
    const bundlePath = join(dir, "bundle.json");
    const badYamlPath = join(dir, "bad.yaml");
    await writeFile(badYamlPath, "participants:\n  - adapter: unknown\n");
    await writeFile(bundlePath, JSON.stringify({
      version: 1,
      defaultProfile: "fast",
      profiles: { fast: { overrides: { rounds: 0 } } },
    }));
    for (const args of [
      [],
      ["--bundle"],
      ["--bundle="],
      ["--profile"],
      ["--profile", "fast"],
      ["--bundle", "--profile", "fast"],
      ["--bundle", "bundle.json", "--profile"],
      ["--bundle", "bundle.json", "--profile="],
      ["--unknown"],
      ["--bundle", "bundle.json", "--unknown"],
      ["--bundle", "bundle.json", "extra"],
    ]) {
      const result = await runCli(dir, args);
      assert.equal(result.code, 1);
      assert.equal(result.stdout, "");
      assert.notEqual(result.stderr, "");
    }

    const failures: Array<{ bundle: unknown; expected: string }> = [
      { bundle: "{", expected: "INVALID_BUNDLE" },
      { bundle: { version: 1, profiles: {} }, expected: "PROFILE_REQUIRED" },
      { bundle: { version: 1, profiles: { fast: { config: "missing.yaml" } } }, expected: "ENOENT" },
      { bundle: { version: 1, profiles: { fast: { config: "bad.yaml" } } }, expected: "debate config" },
      { bundle: { version: 1, profiles: { fast: { extends: "missing" } } }, expected: "UNKNOWN_PROFILE" },
      { bundle: { version: 1, profiles: { fast: { extends: "fast" } } }, expected: "PROFILE_CYCLE" },
      { bundle: { version: 1, profiles: { fast: { config: "../outside.yaml" } } }, expected: "UNSAFE_CONFIG_PATH" },
    ];
    for (const { bundle, expected } of failures) {
      const source = typeof bundle === "string" ? bundle : JSON.stringify(bundle);
      await writeFile(bundlePath, source);
      const args = expected === "PROFILE_REQUIRED"
        ? ["--bundle", "bundle.json"]
        : ["--bundle", "bundle.json", "--profile", "fast"];
      const result = await runCli(dir, args);
      assert.equal(result.code, 1);
      assert.equal(result.stdout, "");
      assert.match(result.stderr, new RegExp(expected));
      assert.equal(await readFile(bundlePath, "utf8"), source);
    }
  });
});
"}

