import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, mkdir, readFile, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { listProfiles, loadProfileBundle } from "../src/profile-bundle.ts";

const CONFIG = [
  "rounds: 2",
  "participants:",
  "  - adapter: claude",
  "    model: sonnet",
  "  - adapter: codex",
  "judge:",
  "  adapter: claude",
  "  model: opus",
  "",
].join("\n");

async function inTempDir(run: (dir: string) => Promise<void>): Promise<void> {
  const dir = await mkdtemp(join(tmpdir(), "disputatio-profile-bundle-"));
  try {
    await run(dir);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

async function expectBundleError(
  action: () => Promise<unknown>,
  code: "INVALID_BUNDLE" | "UNKNOWN_PROFILE" | "PROFILE_REQUIRED" | "PROFILE_CYCLE" | "UNSAFE_CONFIG_PATH",
): Promise<void> {
  await assert.rejects(action, (error: unknown) => {
    assert.ok(error instanceof Error);
    assert.equal((error as { code?: unknown }).code, code);
    return true;
  });
}

test("lists own profile names by Unicode code point without resolving profiles", async () => {
  await inTempDir(async (dir) => {
    const bundlePath = join(dir, "bundle.json");
    const bundleText = JSON.stringify({
      version: 1,
      defaultProfile: { malformed: true },
      profiles: {
        z: null,
        A: { config: "missing.yaml" },
        a: { config: "/unsafe.yaml" },
        10: { extends: "cycle" },
        2: { extends: "10" },
        "\uE000": { config: 7 },
        "\u{10000}": [],
      },
    });
    await writeFile(bundlePath, bundleText);

    const first = await listProfiles(bundlePath);
    assert.deepEqual(first, ["10", "2", "A", "a", "z", "\uE000", "\u{10000}"]);
    first.push("changed");
    assert.deepEqual(await listProfiles(bundlePath), ["10", "2", "A", "a", "z", "\uE000", "\u{10000}"]);
    assert.equal(await readFile(bundlePath, "utf8"), bundleText);
  });
});

test("uses defaultProfile only when selection is omitted", async () => {
